head.script:
// 테스트 설명, 유효성 값 설정
//  ★ _1 : rowIndex/colIndex 를 인덱스(Number) 로 호출하는 핵심 샘플.
//     · colIndex 가 숨겨진 Column 도 포함하여 부여됨을 보이기 위해 comp_init 에서 col2(인덱스 1) 를 setColumnVisible(1, false) 로 숨긴다.
//     · @spec '고정 영역 Cell 의 병합 정보도 반환' 검증을 위해 fixedColumn=2 (col1, col2 고정).
//     · 세로 병합(mergeCells=bycol) 과 가로 병합(mergeCell colSpan=2) 을 둘 다 두어
//       getMergedInfo 가 세로 병합 셀에는 rowIndex 가 확장된 start~end, 가로 병합 셀에는 colIndex 가 확장된 start~end 를 반환함을 보인다.
//     · DrillDown(숨김 Row) / MultiLine 은 _2/_3 담당이라 제외.
scwin.tData = {
    "description" : "[gridView > M > getMergedInfo]<br/>Body Cell 정보를 사용하여 특정 Body Cell 의 병합 정보를 객체로 반환합니다.",
    "validation" : [
        "rowIndex(필수) 파라미터로 병합 정보를 조회할 Body Cell 의 Row 인덱스를 설정합니다. Row 인덱스는 0 부터 시작하며 GridView 에 표시된 Row 를 기준으로 인덱스가 설정됩니다.",
        "colIndex(필수) 파라미터로 병합 정보를 조회할 Body Cell 의 Column 인덱스를 설정합니다. Column 인덱스는 0 부터 시작하며 숨겨진 Column 의 Body Cell 도 포함하여 인덱스가 설정됩니다.",
        "파라미터에 해당하는 Body Cell 의 병합 정보를 객체로 반환하며, result.merged 로 병합 여부(true/false)를 갖습니다.",
        "Body Cell 이 병합 상태이면 result.startRowIndex/startColIndex(병합이 시작된 Cell 의 Row/Column 인덱스), result.endRowIndex/endColIndex(병합이 끝난 Cell 의 Row/Column 인덱스)를 갖습니다.",
        "고정 영역의 Cell 에 대한 병합 정보도 반환합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 검증 데이터 — 세로 병합(bycol 자동) 과 가로 병합(mergeCell 수동) 이 둘 다 드러나도록 구성.
//  행 | col1(고정) | col2(고정,숨김) | col3 | col4
//  ---+-----------+----------------+------+------
//   0 |    A      |      X         |  P   |  1
//   1 |    A      |      X         | [ 가로 병합 R ]
//   2 |    B      |      Y         |  S   |  3
//   3 |    B      |      Y         |  T   |  4
//  · col1(고정,인덱스0) : A,A,B,B → [행0~1]=A / [행2~3]=B 세로병합 (고정 영역 병합 → @spec 검증).
//  · col2(고정,숨김,인덱스1) : X,X,Y,Y → [행0~1]=X / [행2~3]=Y 세로병합 (숨김 Column 도 인덱스 포함 → colIndex=1 로 병합 정보 반환).
//  · col3(인덱스2) : P,R,S,T → 전부 단독값 → 자동 세로병합 없음.
//  · col4(인덱스3) : 1,(흡수),3,4 → 자동 세로병합 없음.
//  · ★ 가로 병합 : comp_init 에서 target1.mergeCell({rowIndex:1, colIndex:2, rowSpan:1, colSpan:2}) 로
//     [행1, col3~col4] 를 가로 병합(colSpan=2) → 세로 병합과 겹치지 않는 비병합 영역에 가로 병합 셀을 만든다.
//     → getMergedInfo(1,2) 는 가로 병합 시작 셀로 startColIndex=2~endColIndex=3(colIndex 확장),
//        getMergedInfo(1,3) 은 가로 병합에 흡수된 셀로 동일 가로 범위를 반환한다.
scwin.MERGE_DATA = [
    { "col1": "A", "col2": "X", "col3": "P", "col4": "1" },
    { "col1": "A", "col2": "X", "col3": "R", "col4": "2" },
    { "col1": "B", "col2": "Y", "col3": "S", "col4": "3" },
    { "col1": "B", "col2": "Y", "col3": "T", "col4": "4" }
];



// comp 생성 : mergeCells="bycol" + fixedColumn=2 그리드 1개를 동적 생성하고, col2(인덱스 1) 를 숨긴다.
scwin.comp_init = async function () {
    // 기존 target / label / DataList 정리 (동일 id 재생성 무시 방지)
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove(dlt_bind.id);
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="mergeCells=bycol(세로 자동병합) + 가로 병합(mergeCell colSpan=2) / fixedColumn=2(col1·col2 고정) / col2(인덱스 1)는 숨김. 인덱스는 숨김 Column 포함(col1=0, col2(숨김)=1, col3=2, col4=3). 세로 병합: col1[행0~1,행2~3], col2(숨김)[행0~1,행2~3]. 가로 병합: [행1, col3~col4]. col3·col4 자동 세로병합 없음"', '', 'label1');

    // DataList 생성 후 검증용 데이터 적재
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON(scwin.MERGE_DATA, false);

    // mergeCells="bycol" (비고정 영역 세로 병합) + mergeCellsFixedCols="bycol" (고정 영역 세로 병합) + fixedColumn=2 (col1, col2 고정)
    //  ★ mergeCells 만으로는 고정 영역(col1·col2)이 병합되지 않으므로, @spec '고정 영역 Cell 병합 정보 반환' 검증을 위해
    //     mergeCellsFixedCols="bycol" 을 함께 설정하여 고정 영역도 세로 병합되도록 한다.
    //     (가로 병합은 자동 옵션이 없으므로 target 생성 후 mergeCell 로 수동 적용한다.)
    let cList = $c.gcm.createCList({
        dataList: "data:" + dlt_bind.id,
        mergeCells: "bycol",
        mergeCellsFixedCols: "bycol",
        fixedColumn: 2,
        defaultCellHeight: 34
    });

    // target 생성
    let grp_comp = document.querySelector('.tc_group_basic');
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' checkAllType="false" id="" style="width:380px;height:200px;">';
    strTarget += '<w2:caption style="" id="caption1" value="getMergedInfo sample"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column1" value="col1(고정)"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column2" value="col2(고정,숨김)"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column3" value="col3"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column4" value="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);

    // ★ col2(인덱스 1) 숨김 → colIndex 가 숨김 Column 을 포함하여 부여됨을 보이기 위함.
    //    (col1=0, col2(숨김)=1, col3=2, col4=3)
    target1.setColumnVisible(1, false);

    // ★ 가로 병합 추가 : [행1, col3(인덱스2)~col4(인덱스3)] 를 가로 병합(colSpan=2).
    //    세로 병합과 겹치지 않는 비병합 영역에 가로 병합 셀을 만들어 getMergedInfo 가
    //    가로 병합 셀에 대해 colIndex 가 확장된 start~end(startColIndex=2~endColIndex=3)를 반환함을 보인다.
    target1.mergeCell({ rowIndex: 1, colIndex: 2, rowSpan: 1, colSpan: 2 });
}



// rowIndex / colIndex 파라미터 수집 (인덱스 Number)
scwin.getRowIndexParam = function () {
    return Number(par_rowIndex.getValue());
};
scwin.getColIndexParam = function () {
    return Number(par_colIndex.getValue());
};



// getMergedInfo 호출 : target1.getMergedInfo(rowIndex, colIndex) 의 반환(병합 정보 객체) 만 간결히 출력한다.
scwin.btn_getMergedInfo_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let rowIndex = scwin.getRowIndexParam();
    let colIndex = scwin.getColIndexParam();

    // getMergedInfo 반환 객체
    let result = target1.getMergedInfo(rowIndex, colIndex);

    // 병합 형태 판정 : getMergedInfo 반환 객체의 start/end 인덱스로만 도출 (DOM 실측 미사용)
    let shape = "";
    if (!result.merged) {
        shape = "병합없음";
    } else if (result.startRowIndex !== result.endRowIndex && result.startColIndex === result.endColIndex) {
        shape = "세로 병합";
    } else if (result.startColIndex !== result.endColIndex && result.startRowIndex === result.endRowIndex) {
        shape = "가로 병합";
    } else if (result.startRowIndex !== result.endRowIndex && result.startColIndex !== result.endColIndex) {
        shape = "블록 병합";
    }

    if (result.merged) {
        bottom.setReturnValue("getMergedInfo(" + rowIndex + ", " + colIndex + ") → {merged:true, start(" + result.startRowIndex + "," + result.startColIndex + ") ~ end(" + result.endRowIndex + "," + result.endColIndex + ")} / 병합 형태 : " + shape);
    } else {
        bottom.setReturnValue("getMergedInfo(" + rowIndex + ", " + colIndex + ") → {merged:false} / 병합 형태 : " + shape);
    }
}
